  ["Stereo module not installed."] = "Modulo stereo non installato.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Gli hook del motore non si sono caricati, quindi tutto ciò che segue è inattivo e il visore usa il semplice percorso mono. O CyberpunkVR_StereoModuleEnable vale 0, oppure esiste bin\\x64\\vrport_nostereo.txt. Vedi la riga \"Stereo:\" in cyberpunkvrport.log.",
  ["LEFT"] = "SINISTRO",
  ["RIGHT"] = "DESTRO",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Stereo attivo  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Nessun secondo occhio al momento -> entrambi gli occhi ricevono MAIN (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Normale nei menu e durante i caricamenti. Se resta così in gioco: il componente VRCAM è spento, oppure vrcam.json indica una telecamera che l'entità del giocatore non ha.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Invio stereo disattivato -> entrambi gli occhi ricevono MAIN (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "età occhio vrcam %u ms  (scaduto oltre %u)   invii occhio %llu",
  ["vrcam eye: never produced a frame"] = "occhio vrcam: mai prodotto un fotogramma",
  ["Send VRCAM to the %s EYE"] = "Invia VRCAM all'OCCHIO %s",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Off = vecchio comportamento, MAIN duplicato in entrambi gli occhi.\nOn = l'occhio %s riceve il colore finale della vista VRCAM --\nla stessa immagine dello specchio sul desktop -- ricodificata nel\nformato sRGB della swapchain e scalata alle dimensioni dell'occhio.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "copie istantanea %llu   salti %llu   hit RTV vrcam %llu",
  ["Eye staleness limit (ms)"] = "Limite di obsolescenza dell'occhio (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Per quanto l'ultimo fotogramma VRCAM resta utilizzabile. Oltre, l'occhio %s\ntorna a MAIN -- un occhio fermo mentre l'altro si muove\nè molto peggio da guardare del mono.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (segue l'upscaler di MAIN, nessun interruttore)",
  ["ON"] = "ACCESA",
  ["off"] = "off",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Attivo quando MAIN esegue l'upscaling con DLSS: vrcam ottiene il suo\nviewport Streamline e renderizza sotto il suo obiettivo.\nSpento con DLAA / TAA / senza upscaler. Si cambia nelle impostazioni\ngrafiche del gioco, non qui.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "Allinea la proiezione VRCAM a MAIN  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "Componente VRCAM  (toggle RTTI: forza ON/OFF)",
  ["component %s   camera %s"] = "componente %s   telecamera %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "nodi vista: main %llu   altri %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "Specchio VRCAM  (finestra separata, per la cattura)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Diagnostica",
  ["Compact ADS camera telemetry (in-headset)"] = "Telemetria compatta della telecamera ADS (nel visore)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Un piccolo pannello che resta visibile dopo la chiusura di F10 e indica cosa ha fatto il MOTORE alla telecamera alzando il mirino:\ndelta e picco in centimetri, destra/avanti/su nella base della direzione, rispetto a un riferimento preso sparando dal fianco.\nL'invio stereo non è influenzato.",
  ["Telemetry X"] = "Telemetria X",
  ["Telemetry Y"] = "Telemetria Y",
  ["Normalised position in the eye image"] = "Posizione normalizzata nell'immagine dell'occhio",
  ["Stereo logging -> cyberpunkvrport.log"] = "Log stereo -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Istantanea consolidata dell'immagine finale VRCAM",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Off = legge direttamente il target temporaneo del motore. Quel target è un'\nallocazione del frame graph che un passaggio successivo riutilizza, ed è ciò che\nfaceva alternare l'immagine chiara/scura. Lasciare attivo.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Istantanea al nodo di tonemap invece di RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "Profiler CPU dei nodi  (ms propri+incl. per nodo)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "fotogramma %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Audit dei nodi -> log  (azzera la finestra)",
  ["top %d by self ms/frame   (main | vrcam)"] = "primi %d per ms propri/fotogramma   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Guida -- mani sul volante",
  ["Grab the wheel with the grips"] = "Afferra il volante con i grilletti laterali",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Durante la GUIDA, porta una mano dove l'animazione di guida tiene il\nvolante (o il manubrio) e premi quel grilletto laterale: il braccio torna\nall'animazione del gioco -- mano sul volante, dita strette\nattorno -- invece di seguire il controller. Rilascia e torna\nalla tua mano.\n\nOgni mano è indipendente: tieni il volante con una e l'altra su\nun'arma. Finché una mano è al volante, quel grilletto non fa altro (niente\nestrazione dalla fondina, niente presa del caricatore).",
  ["Grab radius (m)"] = "Raggio di presa (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Quanto la mano deve essere vicina alla mano animata perché il\ngrilletto conti come presa del volante. Più grande = più facile afferrare un\nvolante che non vedi; troppo grande e ogni presa in auto afferra il volante.",
  ["Car full lock at (deg)"] = "Sterzata completa a (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Sensibilità del volante: rotazione della mano dalla posizione di presa alla sterzata completa.\nUna mano usa un mozzo calibrato dove afferri; due usano la linea che le unisce.\nAggiungere o rilasciare una mano mantiene la sterzata attuale.\n180 = mezzo giro fino a ciascun finecorsa (predefinito). Più basso = più sensibile.\nIl volante nell'abitacolo ha il doppio della corsa nativa; la sterzata delle ruote non cambia.\nLa corsa oltre la sterzata completa mantiene la stessa posizione neutra.",
  ["Steering deadzone (deg)"] = "Zona morta dello sterzo (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Inclinazione attorno al centro che non sterza affatto.\nAumentala se l'auto deriva mentre tieni il volante dritto;\nogni grado qui è un grado di volante morto fuori centro.\nL'intervallo completo finisce comunque a \"Sterzata completa a\", quindi allargare la\nzona morta non fa scattare lo sterzo.",
  ["Steering prediction"] = "Previsione dello sterzo",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Anticipa dolcemente una curva che prosegue dal movimento recente della mano.\nLimitata a 8 ms e 0.5°; il neutro resta invariato.\nLa previsione si ferma con una pausa, un'inversione o un cambio di presa.\nDisattivata per impostazione predefinita. Non può anticipare l'inizio di una curva.",
  ["Prediction horizon (ms)"] = "Orizzonte di previsione (ms)",
  ["Horn -- hand on the wheel hub"] = "Clacson -- mano sul mozzo del volante",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Durante la GUIDA, metti una mano al CENTRO del volante -- dove\ncolpiresti un vero clacson -- e l'auto suona finché resta lì.\nNessun grilletto necessario; una mano che AFFERRA il volante non suona mai.",
  ["Horn hub radius (m)"] = "Raggio del mozzo del clacson (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Quanto vicino al centro del volante la mano conta come sul mozzo.\nPiù grande = clacson più facile da trovare senza guardare; troppo grande\ne arriva al bordo, così ogni presa suona.",
  ["Trigger fires the gun while driving"] = "Il grilletto spara durante la guida",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Estrai un'arma al posto di guida e il GRILLETTO DESTRO smette di essere\nl'acceleratore e diventa l'arma: guida con la mano sinistra sul volante e\nspara con la destra.\n\nL'acceleratore si BLOCCA sul valore che aveva quando hai estratto l'arma, così\nl'auto continua ad andare, e la LEVETTA SINISTRA avanti/indietro regola la velocità mentre\nspari. Riponi l'arma e il grilletto torna a essere l'acceleratore.\n\nFinché l'arma è fuori, l'avanti/indietro della levetta sinistra è usato dalla\nregolazione: niente inclinazione / dondolio né gesto di guida automatica finché non riponi l'arma.",
  ["Throttle trim rate (/s)"] = "Velocità di regolazione dell'acceleratore (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Quanta corsa totale dell'acceleratore la levetta sinistra aggiunge o\ntoglie al secondo quando un'arma è fuori.\n0.5 = due secondi tenuti per andare dal minimo a tavoletta.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "guida %d   al volante  L %d R %d   presa  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "sterzo  %+.1f°  ->  levetta %+.2f     clacson  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "OFFSET TELECAMERA DA SEDUTI",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Gli offset della testa in GENERALE sono una calibrazione in piedi. Da seduti, la telecamera\ndel veicolo del gioco è già dove deve stare -- per questo il port scarta\ni suoi due valori automatici in un veicolo -- quindi un offset in piedi sposta la visuale\nfuori dal sedile invece di correggerla.\n\nQuesti tre si sommano ai cursori della testa quando sei in un veicolo e\nvengono ignorati appena scendi, così auto e strada si regolano\nseparatamente. Zero = l'auto mantiene esattamente l'offset attuale.",
