  ["both eyes observed"] = "ricevuti per entrambi gli occhi",
  ["waiting"] = "in attesa",
  ["CPU: captured frame cadence. GPU: graphics-queue frame interval. Peaks: last 2 seconds."] = "CPU: cadenza dei fotogrammi catturati. GPU: intervallo dei fotogrammi della coda grafica. Picchi: ultimi 2 secondi.",
  ["Output FPS excludes repeated frames; it is not a headset scanout measurement."] = "Gli FPS in uscita escludono i fotogrammi ripetuti; non è una misura della scansione del visore.",
  ["Lows use the mean of the slowest 1%% / 0.1%% of real-frame intervals. Hardware polling: 1 Hz."] = "I minimi usano la media dell'1%% / 0.1%% più lento degli intervalli dei fotogrammi reali. Rilevamento hardware: 1 Hz.",
  ["FPS overlay and statistics are off."] = "Overlay FPS e statistiche sono disattivati.",
  ["Recenter HMD (F7)"] = "Ricentra HMD (F7)",
  ["GENERAL"] = "GENERALE",
  ["CAS Sharpening"] = "Nitidezza CAS",
  ["Contrast-adaptive sharpening for both eyes. 0 = off, 1 = full strength. Disabled automatically with game DLAA."] = "Nitidezza adattiva al contrasto per entrambi gli occhi. 0 = off, 1 = piena intensità. Si disattiva automaticamente con il DLAA del gioco.",
  ["FIXED FOVEATED RENDERING"] = "RENDERING FOVEATO FISSO",
  ["Peripheral quality"] = "Qualità periferica",
  ["Off"] = "Off",
  ["Quality"] = "Qualità",
  ["Balanced"] = "Bilanciato",
  ["Performance"] = "Prestazioni",
  ["The center follows game DLSS/DLAA. Peripheral DLAA uses 100%% / 75%% / 50%% of the game's render resolution."] = "Il centro segue DLSS/DLAA del gioco. Il DLAA periferico usa il 100%% / 75%% / 50%% della risoluzione di rendering del gioco.",
  ["Center width"] = "Larghezza del centro",
  ["Full-quality region width as a percentage of each eye image."] = "Larghezza dell'area a piena qualità in percentuale dell'immagine di ciascun occhio.",
  ["Center height"] = "Altezza del centro",
  ["Full-quality region height as a percentage of each eye image."] = "Altezza dell'area a piena qualità in percentuale dell'immagine di ciascun occhio.",
  ["Center offset X"] = "Offset del centro X",
  ["Percentage of eye-image width. Negative = left, positive = right."] = "Percentuale della larghezza dell'immagine dell'occhio. Negativo = sinistra, positivo = destra.",
  ["Center offset Y"] = "Offset del centro Y",
  ["Percentage of eye-image height. Negative = up, positive = down toward the hands."] = "Percentuale dell'altezza dell'immagine dell'occhio. Negativo = su, positivo = giù verso le mani.",
  ["Show region boundary"] = "Mostra il bordo dell'area",
  ["DLSS GPU: native %.2f ms / foveated %.2f ms"] = "DLSS GPU: nativo %.2f ms / foveato %.2f ms",
  ["Shared sun shadows"] = "Ombre solari condivise",
  ["Render sun cascades once for both eyes. Shadow quality and distance remain controlled by the game."] = "Renderizza le cascate solari una volta per entrambi gli occhi. Qualità e distanza delle ombre restano gestite dal gioco.",
  ["Scope lens stabilization"] = "Stabilizzazione lente del mirino",
  ["Magnifying scope lenses while the view moves: share of the stabilised image (percent). Higher: no blinking of lights and grates, softer. 0 = off. Standing still the lens is untouched."] = "Lenti d'ingrandimento dei mirini mentre la visuale si muove: quota dell'immagine stabilizzata (percentuale). Più alta: niente sfarfallio di luci e grate, più morbida. 0 = off. Da fermi la lente non cambia.",
  ["VARIABLE RATE SHADING"] = "VARIABLE RATE SHADING",
  ["Peripheral shading"] = "Shading periferico",
  [" 2 x 2"] = " 2 x 2",
  [" 4 x 4"] = " 4 x 4",
  ["Opaque scene materials in both eyes. The center stays 1 x 1. Unsupported 4 x 4 falls back to 2 x 2."] = "Materiali opachi della scena in entrambi gli occhi. Il centro resta 1 x 1. Il 4 x 4 non supportato ripiega su 2 x 2.",
  ["Unavailable: GPU resource error"] = "Non disponibile: errore di risorsa GPU",
  ["VRS Tier 2 unavailable"] = "VRS Tier 2 non disponibile",
  ["Preparing"] = "Preparazione",
  ["%s | %u px tiles"] = "%s | tile da %u px",
  ["4 x 4"] = "4 x 4",
  ["2 x 2"] = "2 x 2",
  ["HIDDEN AREA MASK"] = "MASCHERA DELLE AREE NASCOSTE",
  ["Mask lens edges"] = "Maschera i bordi delle lenti",
  ["Skips shading the parts of each eye image the lens never shows. The visible area is unchanged."] = "Evita lo shading delle parti dell'immagine di ciascun occhio che la lente non mostra mai. L'area visibile non cambia.",
  ["Visible radius"] = "Raggio visibile",
  ["Size of the shaded area as a percentage of the eye's field of view: 100%% touches its edges, 141%% masks nothing inside it.\nLower it until a dark border appears at the edge of the lens, then raise it until the border is gone."] = "Dimensione dell'area ombreggiata in percentuale del campo visivo dell'occhio: 100%% ne tocca i bordi, 141%% non maschera nulla all'interno.\nAbbassalo finché sul bordo della lente non compare un contorno scuro, poi alzalo finché non sparisce.",
  ["Waiting for the scene depth"] = "In attesa della profondità della scena",
  ["Masked %.1f %% / %.1f %% of pixels (MAIN / VRCAM)"] = "Mascherati %.1f %% / %.1f %% dei pixel (MAIN / VRCAM)",
  ["GAME MENUS"] = "MENU DI GIOCO",
  ["VR menu quad"] = "Piano del menu VR",
  ["VR menu FOV"] = "FOV del menu VR",
  ["Tracking / Camera"] = "Tracciamento / telecamera",
  ["Locomotion direction is set in the Controls tab."] = "La direzione di movimento si imposta nella scheda Comandi.",
  ["Disable Mouse Y (Pitch)"] = "Disattiva mouse Y (beccheggio)",
  ["Suppress mouse/right-stick pitch so only the HMD controls\nvertical look. Applied by the CET VRIK mod and the\nXInput merge. On by default."] = "Sopprime il beccheggio di mouse/levetta destra così che solo l'HMD controlli\nla visuale verticale. Applicato dalla mod CET VRIK e dalla\nfusione XInput. Attivo per impostazione predefinita.",
  ["Head X right"] = "Testa X destra",
  ["Head Y forward"] = "Testa Y avanti",
  ["Head Z up"] = "Testa Z su",
  ["Debug Gizmos"] = "Gizmo di debug",
  ["Raw hand overlay / debug gizmos:"] = "Overlay grezzo delle mani / gizmo di debug:",
  ["Enable hand overlay"] = "Attiva overlay delle mani",
  ["Draw 3D hand proxy"] = "Disegna mano 3D",
  ["Draw debug wire/axes"] = "Disegna fili/assi di debug",
  ["Locator scale"] = "Scala dei localizzatori",
  ["Verbose log (spammy diag)"] = "Log dettagliato (molta diagnostica)",
  ["Off by default for a clean cyberpunkvrport.log. Enable only\nwhen capturing ClipCursor / depth / hook diagnostics."] = "Disattivato per impostazione predefinita per un cyberpunkvrport.log pulito. Attivalo solo\nper catturare diagnostica ClipCursor / profondità / hook.",
  ["FRAMEGEN"] = "GEN. FOTOGR.",
  ["Enable frame generation"] = "Attiva generazione fotogrammi",
  ["While frame generation is enabled, hand smoothing runs at its rate times xr_hand_lerp_framegen_scale (1.5; 0 turns it off)."] = "Con la generazione fotogrammi attiva, l'attenuazione delle mani gira alla sua frequenza per xr_hand_lerp_framegen_scale (1.5; 0 la disattiva).",
  ["Frame generator"] = "Generatore di fotogrammi",
  ["FidelityFX"] = "FidelityFX",
  ["NVIDIA OFA + FidelityFX"] = "NVIDIA OFA + FidelityFX",
  ["NVIDIA DLSS Frame Generation"] = "NVIDIA DLSS Frame Generation",
  ["DLSS Frame Generation is not available here (%s); FidelityFX is used."] = "DLSS Frame Generation non è disponibile qui (%s); viene usato FidelityFX.",
  ["NVIDIA optical flow is not available on this GPU; FidelityFX optical flow is used."] = "Il flusso ottico NVIDIA non è disponibile su questa GPU; viene usato il flusso ottico FidelityFX.",
  ["NVIDIA quality"] = "Qualità NVIDIA",
  ["Fast (performance)"] = "Veloce (prestazioni)",
  ["Medium (balanced)"] = "Medio (bilanciato)",
  ["Slow (best)"] = "Lento (migliore)",
  ["Optical flow"] = "Flusso ottico",
  ["Off (game vectors only)"] = "Off (solo vettori del gioco)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "I vettori di movimento del gioco descrivono già quasi tutto il movimento; il flusso ottico aggiunge tempo GPU\ne memoria per ciò che sfugge loro (alcune particelle ed effetti).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "Il modello di generazione fotogrammi di NVIDIA su vettori di movimento e profondità del gioco. Massima qualità, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Cadenza adattiva dei fotogrammi reali",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Fino a metà della frequenza del visore. Lascia più tempo GPU ai fotogrammi generati quando i fotogrammi reali vicini vengono persi.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "Usa vettori di movimento e profondità del gioco in entrambi gli occhi. Aggiunge un fotogramma intermedio tra i fotogrammi reali.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "Attiva pannello HUD",
  ["Head / free-look cone"] = "Testa / cono di visuale libera",
  ["Follow"] = "Segui",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Recupera oltre il cono, o dopo 3 secondi di riposo se lo scarto di imbardata supera 10° al suo interno.",
  ["HUD FOV"] = "FOV HUD",
  ["Stereo depth"] = "Profondità stereo",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Off: l'HUD ha la stessa direzione in entrambi gli occhi.\nOn: lo colloca alla profondità fisica scelta.",
  ["Depth"] = "Profondità",
  ["Brightness"] = "Luminosità",
  ["Shadow / outline"] = "Ombra / contorno",
  ["Glow"] = "Bagliore",
  ["INTERACTIONS / DIALOGS"] = "INTERAZIONI / DIALOGHI",
  ["World-space interactions / dialogs"] = "Interazioni / dialoghi nello spazio",
  ["Interaction free-look cone"] = "Cono di visuale libera delle interazioni",
  ["Loot free-look cone"] = "Cono di visuale libera del bottino",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Usato mentre sono visibili il pannello del bottino e la descrizione dell'oggetto. Predefinito: 10°.",
  ["Interaction distance"] = "Distanza delle interazioni",
  ["Interaction FOV"] = "FOV delle interazioni",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "I suggerimenti di interazione e le scelte di dialogo condividono questo pannello. Segue solo oltre il cono; nessun recupero ritardato a riposo.",
  ["Element"] = "Elemento",
  ["Not currently visible in gameplay; settings are still saved."] = "Al momento non visibile in gioco; le impostazioni vengono comunque salvate.",
  ["Show element"] = "Mostra elemento",
  ["Horizontal offset"] = "Offset orizzontale",
  ["Vertical offset"] = "Offset verticale",
  ["Size"] = "Dimensione",
  ["Opacity"] = "Opacità",
  ["Reset element"] = "Ripristina elemento",
  ["Reset all elements"] = "Ripristina tutti gli elementi",
  ["CONTROLS"] = "COMANDI",
  ["DRIVING"] = "GUIDA",
  ["BINDINGS"] = "ASSEGNAZIONI",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Scorciatoie di movimento, mira e interazione fisica.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Mira con la mano  (off = mira VR con la testa separata)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "ON (mira con la mano): il controller punta l'arma e VRIK muove le braccia.\nOFF (mira VR con la testa separata): l'ARMA segue invece la testa, il gioco\nmantiene la sua posizione e le animazioni ADS, e VRIK lascia\nil braccio dell'arma. In ogni caso il colpo parte dalla vera bocca dell'arma, per i proiettili\ncome per gli ordigni lanciati, e la visuale libera durante la mira resta.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Punto laser dell'arma (dove colpisce il proiettile)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Punto rosso proiettato dalla vera direzione della bocca dell'arma attraverso la\ntelecamera del gioco -- segna esattamente dove volerà il proiettile.",
  ["Controller vibration"] = "Vibrazione dei controller",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Aptica: ogni colpo per classe d'arma (pistola, fucile, fucile a pompa, cecchino),\nparata e contrattacco in mischia, blocco e deviazione dei proiettili, raggiungimento di un elemento della cintura,\nrimozione della spoletta di una granata. Presa a due mani: entrambe; a una mano: una.",
  ["Vibration strength"] = "Intensità della vibrazione",
  ["Enable VR -> XInput merge"] = "Attiva fusione VR -> XInput",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Combina (OR) lo stato dei controller VR nel gamepad XInput 0 a ogni lettura.\nOff = il gioco vede solo un pad fisico / niente.",
  ["Weapon holsters (reach + right grip)"] = "Fondine delle armi (raggiungi + grilletto laterale destro)",
  ["Immersive holsters"] = "Fondine immersive",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "ON  - l'arma è scelta dalla fondina VISIBILE che raggiungi:\n      sopra la spalla destra = arma principale (fucile / cecchino),\n      fianco con katana = mischia, fianco con pistola = arma secondaria.\nOFF - fondine visibili ignorate, slot fisso per zona:\n      sopra la spalla = EquipmentSlot1, fianco destro = Slot2, fianco sinistro = Slot3.\nRaggiungi la zona e premi il grilletto laterale DESTRO per equipaggiare / riporre.",
  ["Locomotion direction"] = "Direzione di movimento",
  ["Analog movement"] = "Movimento analogico",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "On: la velocità segue la corsa della levetta sinistra. Off: l'attuale movimento a velocità fissa (predefinito).\nI comandi dei veicoli mantengono la loro risposta attuale.",
  ["Left stick deadzone"] = "Zona morta levetta sinistra",
  ["Right stick deadzone"] = "Zona morta levetta destra",
  ["Full input threshold"] = "Soglia di input completo",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Corsa grezza che dà input analogico completo e attiva scatto, schivata e accovacciamento.\nLa corsa utile tra la zona morta e questa soglia corrisponde a 0-100%%.",
  ["Game (camera)"] = "Gioco (telecamera)",
  ["HMD (head)"] = "HMD (testa)",
  ["Left hand"] = "Mano sinistra",
  ["Right hand"] = "Mano destra",
  ["Move source"] = "Origine del movimento",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Gioco    - la levetta sinistra cammina dove guarda la telecamera (originale).\nHMD      - la levetta sinistra cammina dove guarda il visore.\nMano sin./des. - cammina dove punta il controller scelto.\nI veicoli mantengono sempre la direzione del gioco.",
  ["Breaststroke swimming"] = "Nuoto a rana",
  ["Physical crouch"] = "Accovacciamento fisico",
  ["Physical crouch depth"] = "Profondità dell'accovacciamento fisico",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Perdita di altezza dopo l'inclinazione misurata. Rialzandosi l'accovacciamento fisico termina.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "In acqua: allunga entrambe le mani in avanti, aprile e tira indietro.\nIl movimento inizia durante la trazione. Bracciate leggere nuotano normalmente; trazioni rapide danno spinta.\nNuoti dove punta il visore, anche su/giù; nessuna levetta necessaria.\nPer salire, alza le mani separate all'altezza del petto e spingile entrambe in basso.\nRipeti le bracciate per continuare. Tira la levetta sinistra indietro per fermarti.",
  ["Ladder grip climbing"] = "Arrampicata con presa sulle scale",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Afferra un montante o un piolo. Tira la mano verso il basso per salire,\no muovila verso l'alto per scendere. Rilascia per fermarti. Bacino e gambe nativi restano sulla scala.",
  ["Auto finish near ladder top"] = "Completamento automatico in cima alla scala",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Dopo una trazione verso l'alto vicino alla cima, completa la salita anche se le prese vengono rilasciate.\nMuovi la levetta o spingi in alto una mano che tiene per annullare.",
  ["Ladder finish distance"] = "Distanza di completamento della scala",
  ["Turning (right stick)"] = "Rotazione (levetta destra)",
  ["Snap turn"] = "Rotazione a scatti",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Converte l'asse X della levetta destra in scatti di rotazione\ninvece di una rotazione fluida. Aiuta contro la chinetosi.",
  ["Snap angle"] = "Angolo dello scatto",
  ["STEREO"] = "STEREO",
  ["PERFORMANCE"] = "PRESTAZIONI",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Impostazione del gioco",
  ["Off (higher FPS)"] = "Off (più FPS)",
  ["On (lower latency)"] = "On (latenza minore)",
  ["On + Boost"] = "On + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Off può migliorare l'uso della GPU e gli FPS, ma può aumentare la latenza di input.",
  ["On"] = "On",
  ["Waiting for renderer"] = "In attesa del renderer",
  ["Applied: %s"] = "Applicato: %s",
  ["STEREO VIEW"] = "VISTA STEREO",
  ["Mono mode"] = "Modalità mono",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Un'immagine per entrambi gli occhi, renderizzata una volta dal centro della testa:\nnessuna profondità, il massimo dei fotogrammi. Stereo del motore e seconda vista disattivati.",
  ["Restart the game to apply"] = "Riavvia il gioco per applicare",
  ["Motion prediction (ms)"] = "Previsione del movimento (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Prevede in avanti la posa della testa di questi ms usando la sua\nvelocità, nascondendo la latenza dal rendering ai fotoni. 0 = off.\nAumenta finché il movimento è reattivo senza superare il bersaglio.",
  ["Stereo separation x"] = "Separazione stereo x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Regolazione personale dell'IPD automatico. 1.0 = separazione naturale\ncalibrata, scalata sull'IPD del runtime del visore. Ritocca\n0.8-1.2 a piacere; 3-5x esagera la profondità e rende\nvisibile l'alternanza degli occhi sul monitor per i test.",
  ["World scale"] = "Scala del mondo",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Scala insieme la separazione degli occhi E la traslazione della testa.\nAbbassala (es. 0.8) per far sembrare il mondo\nPIÙ GRANDE / te più piccolo; alzala per rimpicciolire il mondo. Usala se V\ne gli NPC sembrano troppo grandi.",
  ["IPD scale"] = "Scala IPD",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Moltiplicatore della separazione degli occhi sull'IPD del runtime. 1.0 = la base\nneutra (+-0.033 m su un visore tipico).\nInfluisce sulla profondità stereo (diorama o gigante), NON sulla dimensione monoculare.",
  ["Reuse last clean frame"] = "Riusa l'ultimo fotogramma pulito",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Nei tick scaduti, reinvia l'ultimo occhio catturato pulito e lascia che\nil compositore lo riproietti, invece di deformare di nuovo\nil contenuto scaduto. Può abbassare la frequenza di invio\nverso quella di cattura. Off = deforma sempre l'occhio scaduto.",
  ["Asymmetric projection"] = "Proiezione asimmetrica",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "ON: ogni occhio renderizza esattamente la propria finestra di lente decentrata\n(più pannello usato, pixel quadrati).\nOFF: il frustum simmetrico dimensionato sul semiangolo più ampio.",
  ["AVATAR"] = "AVATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "Scorciatoie VR e azioni di gioco predefinite. I nomi dei pulsanti seguono la convenzione Touch / Xbox; le azioni di gioco usano le tue assegnazioni del controller.",
  ["LEFT STICK"] = "LEVETTA SINISTRA",
  ["Move. Hold fully forward for 0.2 seconds to sprint."] = "Muoversi. Tieni tutta in avanti per 0.2 secondi per scattare.",
  ["RIGHT STICK  Left / right"] = "LEVETTA DESTRA  Sinistra / destra",
  ["Turn. Uses your snap-turn setting."] = "Ruotare. Usa la tua impostazione di rotazione a scatti.",
  ["RIGHT STICK  Full up"] = "LEVETTA DESTRA  Tutta su",
  ["Dash / dodge once per push."] = "Scatto / schivata, una volta per spinta.",
  ["RIGHT STICK  Full down"] = "LEVETTA DESTRA  Tutta giù",
  ["Crouch."] = "Accovacciarsi.",
